/* @lc app=leetcode id=3984 lang=kotlin */ class Solution { fun divisibleGame(nums: IntArray): Int = IntArray(1_000_001) { it }.also { sp -> (2..1000).forEach { i -> if (sp[i] == i) (i * i..1_000_000 step i).forEach { if (sp[it] == it) sp[it] = i } } }.let { sp -> (nums.toList().flatMap { x -> generateSequence(x) { r -> (r / sp[r]).takeIf { it > 1 } }.filter { it > 1 }.map { sp[it] }.toList() }.toSet() + 2).sorted().map { p -> nums.fold(Long.MIN_VALUE / 4 to Long.MIN_VALUE / 4) { (cur, best), x -> (maxOf(cur, 0L) + (if (x % p == 0) x else -x)).let { it to maxOf(best, it) } }.second to p }.let { l -> l.maxOf { it.first }.let { mx -> l.first { it.first == mx }.let { (d, p) -> (Math.floorMod(d, 1_000_000_007L) * p % 1_000_000_007L).toInt() } } } } }